AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    IF OBJECT_ID(N'tempdb..#src') IS NOT NULL DROP TABLE #src;
    SELECT * INTO #src FROM (
        SELECT m.ShipMethodID AS ship_method_id, m.Name AS ship_method_name
        FROM stg.ShipMethod AS m
    ) AS q;

    -- unknown member (-1) so facts never lose rows to a missing lookup
    IF NOT EXISTS (SELECT 1 FROM dw.dim_ship_method WHERE ship_method_key = -1)
    BEGIN
        SET IDENTITY_INSERT dw.dim_ship_method ON;
        INSERT INTO dw.dim_ship_method (ship_method_key, ship_method_id, ship_method_name)
        VALUES (-1, -1, 'Unknown');
        SET IDENTITY_INSERT dw.dim_ship_method OFF;
    END;

    -- SCD type 1: overwrite changed attributes (NULL-safe comparison via EXCEPT)
    UPDATE d SET d.ship_method_name = s.ship_method_name, d.etl_updated_at = SYSUTCDATETIME()
    FROM dw.dim_ship_method AS d JOIN #src AS s ON s.ship_method_id = d.ship_method_id
    WHERE EXISTS (SELECT s.ship_method_name EXCEPT SELECT d.ship_method_name);
    SET @rows = @@ROWCOUNT;

    INSERT INTO dw.dim_ship_method (ship_method_id, ship_method_name)
    SELECT s.ship_method_id, s.ship_method_name FROM #src AS s
    WHERE NOT EXISTS (SELECT 1 FROM dw.dim_ship_method AS d WHERE d.ship_method_id = s.ship_method_id);
    SET @rows = @rows + @@ROWCOUNT;

    EXEC etl.usp_log_step @run_id, N'load dim_ship_method', @t0, @rows;
END;
GO
CREATE OR ALTER PROCEDURE etl.usp_load_dim_location @run_id bigint = NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t0 datetime2(3) = SYSUTCDATETIME(), @rows bigint = 0;

    IF OBJECT_ID(N'tempdb..#src') IS NOT NULL DROP TABLE #src;
    SELECT * INTO #src FROM (
        SELECT l.LocationID AS location_id, l.Name AS location_name, l.CostRate AS cost_rate, l.Availability AS availability
        FROM stg.Location AS l
    ) AS q;

    -- unknown member (-1) so facts never lose rows to a missing lookup
    IF NOT EXISTS (SELECT 1 FROM dw.dim_location WHERE location_key = -1)
    BEGIN
        SET IDENTITY_INSERT dw.dim_location ON;
        INSERT INTO dw.dim_location (location_key, location_id, location_name, cost_rate, availability)
        VALUES (-1, -1, 'Unknown', 0, 0);
        SET IDENTITY_INSERT dw.dim_location OFF;
    END;

    -- SCD type 1: overwrite changed attributes (NULL-safe comparison via EXCEPT)
    UPDATE d SET d.location_name = s.location_name, d.cost_rate = s.cost_rate, d.availability = s.availability, d.etl_updated_at = SYSUTCDATETIME()
    FROM dw.dim_location AS d JOIN #src AS s ON s.location_id = d.location_id
    WHERE EXISTS (SELECT s.location_name, s.cost_rate, s.availability EXCEPT SELECT d.location_name, d.cost_rate, d.availability);
    SET @rows = @@ROWCOUNT;

    INSERT INTO dw.dim_location (location_id, location_name, cost_rate, availability)
    SELECT s.location_id, s.location_name, s.cost_rate, s.availability FROM #src AS s
    WHERE NOT EXISTS (SELECT 1 FROM dw.dim_location AS d WHERE d.location_id = s.location_id);
    SET @rows = @rows + @@ROWCOUNT;

    EXEC etl.usp_log_step @run_id, N'load dim_location', @t0, @rows;
END;
GO
